 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] != 0:
                        seen[ny][nx] = True
                        q.append((ny, nx))

            remaining = set(cells)
            layers = []
            while remaining:
                min_r = min(y for y, x in remaining)
                max_r = max(y for y, x in remaining)
                min_c = min(x for y, x in remaining)
                max_c = max(x for y, x in remaining)
                color = grid[min_r][min_c]
                layers.append(color)
                remaining = {(y, x) for y, x in remaining if grid[y][x] != color}

            reverse_layers = layers[::-1]
            color_map = dict(zip(layers, reverse_layers))
            for y, x in cells:
                out[y][x] = color_map[grid[y][x]]
    return out
